SZGame2D.onStart(function __szProjectRun() {
  const __szProjectRunContext = window.__SZProjectLifecycle.begin(() => SZGame2D.restart());
  // Ao iniciar
  SZGame2D.setupStage(480, 270, "#81d4fa");
  SZGame2D.setStageDescription("Corra com o dino e pule os cactos apertando espaço");
  const dino = SZGame2D.createDino({ x: 110, y: 150, size: 64, color: "#8b5cf6" });
  const cactos = SZGame2D.createGroup();
  SZGame2D.setScene("inicio");
  SZGame2D.setHitboxScale(dino, 80);
  let pontos = 0;
  // Quando acontecer
  SZGame2D.onJump(() => dino, () => {
      SZGame2D.playFx("jump");
    }, "dino-ref-67");
  SZGame2D.onAnyInput(() => {
      if (SZGame2D.sceneIs("inicio")) {
      SZGame2D.setScene("jogando");
    } else if (SZGame2D.sceneIs("fim")) {
      SZGame2D.restart();
    }
    }, "dino-ref-69");
  // Enquanto estiver rodando
  // O jogo roda 60 passos por segundo: cada volta desenha um "quadro" do filme.
  SZGame2D.gameLoop(function update() {
    SZGame2D.clear();
    SZGame2D.drawForest(ctx, 5);
    if (SZGame2D.sceneIs("jogando")) {
      SZGame2D.applyGravity(dino);
      SZGame2D.controlDino(dino, ctx, 14);
      SZGame2D.drawSprite(ctx, dino);
      SZGame2D.updateGroup(cactos);
      SZGame2D.drawGroup(ctx, cactos);
      SZGame2D.overlapSpriteGroup(() => dino, cactos, (cacto) => {
        SZGame2D.explodeSprite(cacto, "#ffab00");
        SZGame2D.shake(ctx, 8);
        SZGame2D.playFx("gameover");
        SZGame2D.setScene("fim");
      });
      SZGame2D.pruneOffscreen(ctx, cactos, 40, (cacto) => {

      });
      SZGame2D.drawScore(ctx, "Pontos:", pontos, 12, 30, "#102030", 24);
    } else if (SZGame2D.sceneIs("inicio")) {
      SZGame2D.showScreen(ctx, "Corre, Dino!", "Pule os cactos!", "Aperte qualquer tecla ou toque na tela para começar", "#102030");
    } else if (SZGame2D.sceneIs("fim")) {
      SZGame2D.showScreen(ctx, "Fim de jogo", `Você fez ${pontos} pontos. Tente bater essa marca!`, "Aperte qualquer tecla ou toque para jogar de novo", "#102030");
    }
  }, "dino-ref-16");
  SZGame2D.gameLoop(function __szPeriodicLoop() {
    if (SZGame2D.everySeconds("cada", 1.4)) {
      if (SZGame2D.sceneIs("jogando")) {
        SZGame2D.spawnObstacle(cactos, ctx, { type: "cactus", x: 560, size: 44, vx: -5 });
      }
    }
  });
  SZGame2D.gameLoop(function __szPeriodicLoop() {
    if (SZGame2D.everySeconds("cada_2", 1)) {
      if (SZGame2D.sceneIs("jogando")) {
        pontos = pontos + 1;
      }
    }
  });
}, "__sz-project");
